namespace Mist.Tests.OptionalLocalWorks;

public static class SettlementSupportCases
{
    private static readonly Mist.Core.Content.RuntimeCatalog Catalog=Q102.Q102Cases.Catalog();
    public static SettlementSupportContract Contract()=>SettlementSupportContract.ParseJson(File.ReadAllText(Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../..","content/source/optional_local_works/settlement_support_contracts.json"))));
    private static ProfileStore Store(string label)=>new(Path.Combine(Environment.GetEnvironmentVariable("MISTSEA_TEST_OUTPUT")??Path.GetTempPath(),"settlement-normal-"+label+"-"+Guid.NewGuid()),Catalog.ReleaseId);
    private static void Success(CommandResult r)=>Require(r.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,StrictJson.Serialize(r));
    public static string MainWorld(BranchSnapshot s)=>StrictJson.Serialize(new{entities=s.Entities.Where(e=>e.Id!="actor"&&!e.Id.StartsWith("R6-O01:",StringComparison.Ordinal)&&!e.Id.StartsWith("R6-O02:",StringComparison.Ordinal)&&!e.Id.StartsWith("material:R6-LOCAL-",StringComparison.Ordinal)).OrderBy(e=>e.Id),items=s.Items.Where(i=>!i.Id.StartsWith("R6-O01-",StringComparison.Ordinal)&&!i.Id.StartsWith("R6-O02-",StringComparison.Ordinal)).OrderBy(i=>i.Id),balances=s.Balances.OrderBy(x=>x.Key)});
    public sealed class Run
    {
        public ProfileStore Store {get;}public ChapterSixCases.Run Chapter {get;}public SettlementSupportService Service {get;}
        public SettlementSupportView View=>Done(Service.ViewAsync());
        public Run(ProfileStore s,bool ready=true){Store=s;var p=ChapterSixCases.ActualArrival(s);Chapter=new(s,p.Service,p.Interior);Service=new(s,p.Service,Contract());if(ready){Chapter.Node601();Chapter.RidgeReady();Chapter.Base("R6");Chapter.Node603();}}
        public void Discover(string id){Chapter.Material(id=="O-R6-01"?"R6-O01-R-NEEDS":"R6-O02-R-MAINTENANCE");Success(Done(Service.DiscoverAsync(id)));}
        public void At(string spot)=>Chapter.At(spot);
        public void Note(string task,params (string Key,string Value)[] fields){var d=Done(Store.GetDraftAsync(task));Done(Service.SaveDraftAsync(task,d?.Revision??0,d?.Id,"This bounded local note retains the actual sources, places and work stages. It records the separately verified same physical objects and original ownership. The private family note was not opened. These optional results award no main resources or ending qualification."));Success(Done(Service.ConfirmMeaningAsync(task,fields.ToImmutableDictionary(x=>x.Key,x=>x.Value),true)));}
        public void PacketReady(){Discover("O-R6-01");Success(Done(Service.DecidePacketAsync("accept")));Success(Done(Service.CompareForecastsAsync("current_survey_stage","southern_inlet","earlier_arrival_stage","marked_leeward","sheltered_return")));At("R6-S05.manifest");Success(Done(Service.InspectExtraStockAsync(SettlementSupportService.PacketSerials.ToArray())));Success(Done(Service.DispatchPacketAsync(SettlementSupportService.PacketSerials.ToArray(),"ROLE-R6-CART-DRIVER","ROLE-R6-CARGO-WATCH")));At("R6-O01.notice");Note(SettlementSupportService.PacketTask,("route","marked_leeward"),("fallback","sheltered_return"),("windows","different_places_and_stages"),("stock","three_optional_serials"),("scope","extra_only_no_ending"));}
        public void PressReady(){Discover("O-R6-02");Success(Done(Service.DecidePressAsync("accept")));Success(Done(Service.RequestPressPermissionAsync("service_interval","ROLE-R6-O02-OPERATOR","ROLE-R6-O02-CUSTODIAN","manual_reserve")));Success(Done(Service.InspectManualReserveAsync(["R6-O02-MANUAL-01","R6-O02-MANUAL-02"])));Success(Done(Service.SetPressInputAsync("OFF")));Success(Done(Service.LatchPressJawAsync(true)));Success(Done(Service.VerifyPressZeroAsync("DRIVE",0,View.Press!.Configuration)));Note(SettlementSupportService.PressTask,("window","service_interval"),("operator","ROLE-R6-O02-OPERATOR"),("reviewer","ROLE-R6-O02-CUSTODIAN"),("fallback","manual_reserve"),("scope","isolated_press_only"));}
        public void LampReady(string arrangement="return_same_lamp"){Discover("O-R6-02");Success(Done(Service.DecideLampAsync("accept")));Success(Done(Service.RequestLampPermissionAsync(SettlementSupportService.LampOwner,SettlementSupportService.LampBorrower,"same_lamp_service_return_only")));Success(Done(Service.InspectLampAsync(SettlementSupportService.LampSerial)));Success(Done(Service.SetLampInputAsync("OFF")));Success(Done(Service.LatchLampCoverAsync()));Success(Done(Service.VerifyLampZeroAsync("DRIVE",0,View.Lamp!.Configuration)));Success(Done(Service.ServiceSameLampAsync(SettlementSupportService.LampSerial)));Success(Done(Service.VerifyLampZeroAsync("DRIVE",0,View.Lamp!.Configuration)));Success(Done(Service.CarrySameLampAsync(arrangement)));At("R6-O01.notice");Success(Done(Service.OwnerReceiveLampAsync(SettlementSupportService.LampOwner,arrangement,"manual_reserve")));Note(SettlementSupportService.LampTask,("serial",SettlementSupportService.LampSerial),("owner",SettlementSupportService.LampOwner),("arrangement",arrangement),("fallback","manual_reserve"),("privacy","family_note_not_opened"),("scope","same_serviced_returned_lamp_only"));}
    }
    public static void Register()
    {
        Add("CP-SETTLEMENT-03","Normal current-stage and earlier southern forecasts require exact finite optional batch and actual new delivery route; preview cancel and once receipt preserve main world",()=>
        {using var s=Store("packet");var r=new Run(s);r.Discover("O-R6-01");string main=MainWorld(Done(s.SnapshotAsync()));Success(Done(r.Service.DecidePacketAsync("accept")));long seq=s.Session.Sequence;Throws<InvalidOperationException>(()=>Done(r.Service.CompareForecastsAsync("current_survey_stage","southern_inlet","current_survey_stage","low_cut","sheltered_return")));Require(s.Session.Sequence==seq);Success(Done(r.Service.CompareForecastsAsync("current_survey_stage","southern_inlet","earlier_arrival_stage","marked_leeward","sheltered_return")));r.At("R6-S05.manifest");Throws<InvalidOperationException>(()=>Done(r.Service.InspectExtraStockAsync(["R6-finite:BASE-TWR-R6-base_isolator:1"])));Success(Done(r.Service.InspectExtraStockAsync(SettlementSupportService.PacketSerials.ToArray())));Success(Done(r.Service.DispatchPacketAsync(SettlementSupportService.PacketSerials.ToArray(),"ROLE-R6-CART-DRIVER","ROLE-R6-CARGO-WATCH")));Throws<InvalidOperationException>(()=>Done(r.Service.PreviewPacketDeliveryAsync()));r.At("R6-O01.notice");r.Note(SettlementSupportService.PacketTask,("route","marked_leeward"),("fallback","sheltered_return"),("windows","different_places_and_stages"),("stock","three_optional_serials"),("scope","extra_only_no_ending"));seq=s.Session.Sequence;var p=Done(r.Service.PreviewPacketDeliveryAsync());Require(p.Ready&&s.Session.Sequence==seq);r.Service.ClosePreview(p.Token);Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq);p=Done(r.Service.PreviewPacketDeliveryAsync());Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));var snap=Done(s.SnapshotAsync());Require(r.View.Packet!.Delivered&&snap.Receipts.Count(x=>x.SemanticKey==SettlementSupportService.PacketId+":resolution")==1&&SettlementSupportService.PacketSerials.All(id=>snap.Items.Single(i=>i.Id==id) is{OwnerKind:"installed",OwnerId:SettlementSupportService.Receiver})&&MainWorld(snap)==main&&snap.Receipts.All(x=>!x.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)));});
        Add("CP-SETTLEMENT-03","Real shared press requires separate local posts, dedicated manual reserve and current DRIVE zero; permission withdrawal and Continue reject stale handovers",()=>
        {using var s=Store("press");var r=new Run(s);r.Discover("O-R6-02");string main=MainWorld(Done(s.SnapshotAsync()));Success(Done(r.Service.DecidePressAsync("accept")));Throws<InvalidOperationException>(()=>Done(r.Service.RequestPressPermissionAsync("service_interval","ROLE-R6-O02-OPERATOR","ROLE-R6-O02-OPERATOR","manual_reserve")));r.PressReady();Throws<InvalidOperationException>(()=>Done(r.Service.VerifyPressZeroAsync("REF",10,r.View.Press!.Configuration)));var p=Done(r.Service.PreviewPressResponsibilityAsync());Success(Done(r.Service.DecidePressAsync("withdraw")));Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected);r.PressReady();p=Done(r.Service.PreviewPressResponsibilityAsync());Done(s.ContinueAsync());Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected);p=Done(r.Service.PreviewPressResponsibilityAsync());Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));Require(r.View.Press is{Completed:true,Input:"OFF",JawLatched:true}&&MainWorld(Done(s.SnapshotAsync()))==main&&Done(s.SnapshotAsync()).Items.Count(i=>i.Id==SettlementSupportService.PressSerial)==1);});
        Add("CP-SETTLEMENT-03","Same borrowed lamp cannot expose family note, use another serial or reuse old zero after cleaning; actual return and bounded mutual aid keep original title once",()=>
        {
            using var s=Store("lamp");var r=new Run(s);r.Discover("O-R6-02");
            // First real travel registers its legitimate current connection. Include that in the
            // baseline; an earlier visit must still never count as this lamp's later delivery.
            r.At("R6-O01.notice");r.At("R6-O02.notice");var before=Done(s.SnapshotAsync());string main=MainWorld(before);
            Require(before.Entities.Any(e=>e.Id=="travel-gate:R6-O01:R6-S03"),"The owner's actual paired route was not inspected and registered before the unchanged-world baseline.");
            Success(Done(r.Service.DecideLampAsync("accept")));
            Throws<InvalidOperationException>(()=>Done(r.Service.RequestLampPermissionAsync(SettlementSupportService.LampOwner,SettlementSupportService.LampBorrower,"publish_family_note")));
            Success(Done(r.Service.RequestLampPermissionAsync(SettlementSupportService.LampOwner,SettlementSupportService.LampBorrower,"same_lamp_service_return_only")));
            Throws<InvalidOperationException>(()=>Done(r.Service.InspectLampAsync("another-lamp")));
            Success(Done(r.Service.InspectLampAsync(SettlementSupportService.LampSerial)));Success(Done(r.Service.SetLampInputAsync("OFF")));Success(Done(r.Service.LatchLampCoverAsync()));
            Success(Done(r.Service.VerifyLampZeroAsync("DRIVE",0,r.View.Lamp!.Configuration)));Success(Done(r.Service.ServiceSameLampAsync(SettlementSupportService.LampSerial)));
            Throws<InvalidOperationException>(()=>Done(r.Service.CarrySameLampAsync("finite_mutual_aid")));
            Success(Done(r.Service.VerifyLampZeroAsync("DRIVE",0,r.View.Lamp!.Configuration)));Success(Done(r.Service.CarrySameLampAsync("finite_mutual_aid")));
            Throws<InvalidOperationException>(()=>Done(r.Service.OwnerReceiveLampAsync(SettlementSupportService.LampOwner,"finite_mutual_aid","manual_reserve")));
            r.At("R6-O01.notice");Success(Done(r.Service.OwnerReceiveLampAsync(SettlementSupportService.LampOwner,"finite_mutual_aid","manual_reserve")));
            r.Note(SettlementSupportService.LampTask,("serial",SettlementSupportService.LampSerial),("owner",SettlementSupportService.LampOwner),("arrangement","finite_mutual_aid"),("fallback","manual_reserve"),("privacy","family_note_not_opened"),("scope","same_serviced_returned_lamp_only"));
            var p=Done(r.Service.PreviewLampHandoverAsync());Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));var snap=Done(s.SnapshotAsync());
            Require(snap.Items.Single(i=>i.Id==SettlementSupportService.LampSerial) is{OwnerKind:"warehouse",OwnerId:SettlementSupportService.LampOwner},"The same borrowed lamp did not remain in the original owner's real custody.");
            Require(snap.Receipts.Count(x=>x.SemanticKey==SettlementSupportService.LampId+":resolution")==1,"The local lamp arrangement was not accepted exactly once.");
            var result=StrictJson.Deserialize<BorrowedLampResult>(snap.Entities.Single(e=>e.Id==SettlementSupportService.LampId+":result").Json);long dispatched=r.View.Lamp!.DispatchSequence;
            Require(result.TraversalReceipts.Length>0&&result.TraversalReceipts.All(id=>snap.Receipts.Single(x=>x.ReceiptId==id).Sequence>dispatched)&&before.Receipts.Where(x=>x.ActionType=="scene_transition").All(x=>!result.TraversalReceipts.Contains(x.ReceiptId)),"A pre-dispatch owner visit was counted as physical lamp delivery.");
            Require(MainWorld(snap)==main,"Borrowed-lamp work changed protected world, other items or balances after the actual route baseline.");
        });
        Add("CP-SETTLEMENT-03","Saved optional prose has real CAS and no world execution; changed prose invalidates a delivery confirmation without losing the carried physical packet",()=>
        {using var s=Store("draft");var r=new Run(s);r.PacketReady();var p=Done(r.Service.PreviewPacketDeliveryAsync());var d=Done(s.GetDraftAsync(SettlementSupportService.PacketTask))!;Done(r.Service.SaveDraftAsync(SettlementSupportService.PacketTask,d.Revision,d.Id,d.Body+" Revised."));Throws<StoreConflictException>(()=>Done(r.Service.SaveDraftAsync(SettlementSupportService.PacketTask,d.Revision,d.Id,"old overwrite")));Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected&&!r.View.Packet!.Delivered&&SettlementSupportService.PacketSerials.All(id=>Done(s.SnapshotAsync()).Items.Single(i=>i.Id==id).OwnerId==SettlementSupportService.PacketId+":courier"));});
        Add("CP-SETTLEMENT-05","Actual zero-XP prior chapters and Q603 export a native settlement entry with no local permission, finite stock or completion fixture",()=>
        {using var s=Store("native-entry");var r=new Run(s);r.At("R6-O01.notice");var snap=Done(s.SnapshotAsync());Require(snap.Balances["experience"]==13700&&r.View.Packet is null&&r.View.Press is null&&r.View.Lamp is null&&!snap.Items.Any(i=>i.Id.StartsWith("R6-O01-",StringComparison.Ordinal)||i.Id.StartsWith("R6-O02-",StringComparison.Ordinal))&&snap.Receipts.All(x=>!x.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)&&!x.SemanticKey.StartsWith("internal:",StringComparison.Ordinal)));Done(s.CreateCheckpointAsync("manual"));File.WriteAllText(Path.Combine(s.RootPath,"normal-settlement-native-entry.json"),StrictJson.Serialize(new{scope="actual zero-XP through Q603, real paired travel to R6-O01; all local settlement work remains unaccepted",profile_root=s.RootPath,experience=13700,actor=r.Chapter.View.Actor,receipts=snap.Receipts,human_native_play="not_run",physical_ime="not_run",language_review="human_pending"}));});
    }
}
